import { useState } from "react";
import { MdEdit, MdDelete } from "react-icons/md";
import Image from "next/image";
import { useCategories } from "@/hooks/useCategories";
import Pagination from "@/components/category/Pagination";
import SearchBar from "@/components/category/SearchBar";
import CategoryModal from "@/components/category/CategoryModal";

const CategoryTable = () => {
  const { data, isLoading } = useCategories();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [categoryToEdit, setCategoryToEdit] = useState(null);

  const handleEdit = (category) => {
    setCategoryToEdit(category);
    setIsModalOpen(true);
  };

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <div className="flex justify-between mb-6">
        <h2 className="text-3xl font-semibold text-gray-800">📦 Category Management</h2>
        <button 
          className="bg-blue-500 text-white px-6 py-3 text-lg font-medium rounded-lg shadow-md hover:bg-blue-600 transition"
          onClick={() => {
            setCategoryToEdit(null);
            setIsModalOpen(true);
          }}
        >
          + Create Category
        </button>
      </div>

      <SearchBar />

      <div className="space-y-4 mt-6">
        {data?.content.map((category) => (
          <div key={category.categoryId} className="flex justify-between bg-gray-100 p-4 rounded-lg">
            <Image src={category.categoryPicture} width={50} height={50} className="rounded-lg" />
            <p>{category.categoryName}</p>
            <button onClick={() => handleEdit(category)}><MdEdit /></button>
          </div>
        ))}
      </div>

      <Pagination />

      <CategoryModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} categoryToEdit={categoryToEdit} />
    </div>
  );
};

export default CategoryTable;
