import { useState, useEffect } from "react";
import axios from "axios";

const CategoryModal = ({ isOpen, onClose, category }) => {
  const [categoryName, setCategoryName] = useState("");
  const [categoryPicture, setCategoryPicture] = useState("");

  useEffect(() => {
    if (category) {
      setCategoryName(category.categoryName);
      setCategoryPicture(category.categoryPicture);
    } else {
      setCategoryName("");
      setCategoryPicture("");
    }
  }, [category]);

  const handleSubmit = async () => {
    try {
      if (category) {
        // ✅ Update existing category
        await axios.put(`/api/categories/${category.categoryId}`, { categoryName, categoryPicture });
      } else {
        // ✅ Create new category
        await axios.post(`/api/categories`, { categoryName, categoryPicture });
      }
      onClose(); // ✅ Close modal after success
    } catch (error) {
      console.error("Error saving category:", error);
    }
  };

  return (
    <div className={`fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 ${isOpen ? "block" : "hidden"}`}>
      <div className="bg-white p-6 rounded-lg shadow-lg w-96">
        <h2 className="text-2xl font-semibold mb-4">{category ? "Edit Category" : "Create Category"}</h2>

        <label className="block text-sm font-medium text-gray-700">Category Name</label>
        <input
          type="text"
          className="w-full px-4 py-2 border rounded-md mt-1"
          value={categoryName}
          onChange={(e) => setCategoryName(e.target.value)}
        />

        <label className="block text-sm font-medium text-gray-700 mt-4">Category Picture URL</label>
        <input
          type="text"
          className="w-full px-4 py-2 border rounded-md mt-1"
          value={categoryPicture}
          onChange={(e) => setCategoryPicture(e.target.value)}
        />

        <div className="flex justify-end mt-4">
          <button className="mr-2 px-4 py-2 bg-gray-400 text-white rounded-md" onClick={onClose}>
            Cancel
          </button>
          <button className="px-4 py-2 bg-blue-500 text-white rounded-md" onClick={handleSubmit}>
            {category ? "Update" : "Create"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default CategoryModal;
